	STRING ASIS	BLANKS OFF************************************************************************	GraphiCard Driver version 2.0*   	Copyright Apple Computer, Inc. 1986-1989*	All rights reserved.***********************************************************************	MACRO&lab	str &string	EXPORT &lab						; export the label	LCLC &EIB						; declare a temporary var to hold current string setting&EIB	SETC &SETTING('STRING') ; put current string setting into temp	STRING PASCAL					; Set string type to pascal.&lab	DC.B	&string 				; make the string	STRING &EIB 					; restore orig string settings	MEND;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY But1	ENTRY Msg1_320	ENTRY Msg1_640	ENTRY item1_320	ENTRY item1_640	ENTRY item2_320	ENTRY item2_640		INCLUDE 'e16.dialog'	EXPORT DialogDataDialogData	PROC;------------------------------------------------------------;; data used by manual feed alert box;;------------------------------------------------------------;; 640 mode; 	EXPORT alerttemp640alerttemp640	DC.W 30,40,75,600	; bounds rect	DC.W 1301	; id	DC.B $80	DC.B $80	DC.B $80	DC.B $80	DC.L item1_640	; Continue	DC.L item2_640	; text	DC.L 0000	EXPORT item1_640item1_640	DC.W 1	; id	DC.W 22,470,0,0	; bounds rect for button	DC.W ButtonItem	; type	DC.L But1	; item descriptor -	'Continue'	DC.W 00	; item value	DC.W 0	; item flag	DC.L 0	; item color	EXPORT item2_640item2_640	DC.W 2	; id	DC.W 3,100,43,400	; bounds rect for button	DC.W LongStatText	; type	DC.L Msg1_640	; item descriptor	DC.W Len_Msg1_640	; item value	DC.W 0	; item flag	DC.L 0	; item color	EXPORT But1But1	str 'OK'	EXPORT Msg1_640Msg1_640	DC.B $0d	DC.B 'The Print Manager cannot find a parallel'	DC.B $0d	DC.B 'card with which it can work.'Len_Msg1_640	equ *-Msg1_640;------------------------------------------------------------;; 320 mode; 	EXPORT alerttemp320alerttemp320	DC.W 30,10,95,310	; bounds rect	DC.W 1301	; id	DC.B $80	DC.B $80	DC.B $80	DC.B $80	DC.L item1_320	; Continue	DC.L item2_320	; text	DC.L 0000	EXPORT item1_320item1_320	DC.W 1	; id	DC.W 45,235,0,0	; bounds rect for button	DC.W ButtonItem	; type	DC.L But1	; item descriptor -	'Continue'	DC.W 00	; item value	DC.W 0	; item flag	DC.L 0	; item color	EXPORT item2_320item2_320	DC.W 2	; id	DC.W 3,55,63,225	; bounds rect for text	DC.W LongStatText	; type	DC.L Msg1_320	; item descriptor	DC.W Len_Msg1_320	; item value	DC.W 0	; item flag	DC.L 0	; item color	EXPORT Msg1_320Msg1_320	DC.B $0d	DC.B 'The Print Manager'	DC.B $0d	DC.B 'cannot find a parallel'	DC.B $0d	DC.B 'card with which it'	DC.B $0d	DC.B 'can work.'	DC.B $0dLen_Msg1_320	equ *-Msg1_320	ENDP	END